<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';if(is_file(__DIR__.'/app/access_control_v1300.php'))require_once __DIR__.'/app/access_control_v1300.php';require_once __DIR__.'/app/services_v1380.php';sk1380_require_login('/my-services.php');$order=sk1380_order((int)($_GET['id']??0));if(!$order){http_response_code(404);exit('Booking not found.');}$p=sk1380_provider();$isProvider=$p&&(int)$p['id']===(int)$order['provider_id'];$isCustomer=(int)$order['customer_user_id']===sk1380_uid();$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{sk1380_csrf_check();$act=(string)$_POST['action'];if($act==='message'){$text=trim((string)$_POST['message']);if($text==='')throw new RuntimeException('Message is empty.');sk1380_db()->prepare('INSERT INTO service_messages_v1380(tenant_id,order_id,sender_user_id,message,created_at) VALUES(?,?,?,?,NOW())')->execute([sk1380_tid(),$order['id'],sk1380_uid(),substr($text,0,2000)]);$msg='Message sent.';}elseif($act==='status'&&($isProvider||sk1380_admin())){$next=(string)$_POST['status'];$allowed=['accepted','on_the_way','started','completed'];if(!in_array($next,$allowed,true))throw new RuntimeException('Invalid status.');$set=$next==='completed'?',completed_at=NOW()':'';sk1380_db()->prepare('UPDATE service_orders_v1380 SET status=?'.$set.',updated_at=NOW() WHERE tenant_id=? AND id=?')->execute([$next,sk1380_tid(),$order['id']]);sk1380_log_order((int)$order['id'],$next,trim((string)($_POST['note']??'')));if($next==='completed'){sk1380_db()->prepare('UPDATE service_provider_profiles_v1380 SET completed_orders=completed_orders+1,updated_at=NOW() WHERE tenant_id=? AND id=?')->execute([sk1380_tid(),$order['provider_id']]);}$msg='Booking status updated.';}elseif($act==='review'&&$isCustomer&&$order['status']==='completed'){$rating=max(1,min(5,(int)$_POST['rating']));$text=trim((string)($_POST['review_text']??''));$pdo=sk1380_db();$pdo->prepare('INSERT INTO service_reviews_v1380(tenant_id,order_id,provider_id,customer_user_id,rating,review_text,status,created_at,updated_at) VALUES(?,?,?,?,?,?,"published",NOW(),NOW()) ON DUPLICATE KEY UPDATE rating=VALUES(rating),review_text=VALUES(review_text),updated_at=NOW()')->execute([sk1380_tid(),$order['id'],$order['provider_id'],sk1380_uid(),$rating,$text?:null]);$pdo->prepare('UPDATE service_provider_profiles_v1380 p SET rating_count=(SELECT COUNT(*) FROM service_reviews_v1380 r WHERE r.tenant_id=p.tenant_id AND r.provider_id=p.id AND r.status="published"),rating_avg=COALESCE((SELECT AVG(r.rating) FROM service_reviews_v1380 r WHERE r.tenant_id=p.tenant_id AND r.provider_id=p.id AND r.status="published"),0),updated_at=NOW() WHERE p.tenant_id=? AND p.id=?')->execute([sk1380_tid(),$order['provider_id']]);$msg='Review saved.';}header('Location: /service-order.php?id='.$order['id'].'&ok='.urlencode($msg));exit;}catch(Throwable $e){$err=$e->getMessage();}}$msg=$msg?:trim((string)($_GET['ok']??''));$order=sk1380_order((int)$order['id']);$q=sk1380_db()->prepare('SELECT e.* FROM service_order_events_v1380 e WHERE e.tenant_id=? AND e.order_id=? ORDER BY e.id');$q->execute([sk1380_tid(),$order['id']]);$events=$q->fetchAll(PDO::FETCH_ASSOC)?:[];$q=sk1380_db()->prepare('SELECT m.* FROM service_messages_v1380 m WHERE m.tenant_id=? AND m.order_id=? ORDER BY m.id');$q->execute([sk1380_tid(),$order['id']]);$messages=$q->fetchAll(PDO::FETCH_ASSOC)?:[];sk1380_shell('Booking '.$order['order_code'],'order');?><section class="order-head"><div><span><?=sk1380_h($order['order_code'])?></span><h1><?=sk1380_h($order['service_title'])?></h1><p><?=sk1380_h($order['area'])?> · <?=sk1380_h($order['business_name']?:$order['display_name'])?></p></div><div class="order-state"><?=sk1380_h(strtoupper($order['status']))?><strong>PKR <?=number_format((float)$order['total_amount'],0)?></strong></div></section><?php if($msg):?><div class="notice ok"><?=sk1380_h($msg)?></div><?php endif;?><?php if($err):?><div class="notice err"><?=sk1380_h($err)?></div><?php endif;?><div class="order-grid"><section><h2>Service address</h2><p><?=nl2br(sk1380_h($order['address_text']))?></p><h2>Job timeline</h2><div class="timeline"><?php foreach($events as $e):?><div><b><?=sk1380_h(str_replace('_',' ',strtoupper($e['status_code'])))?></b><span><?=sk1380_h(date('d M Y, h:i A',strtotime($e['created_at'])))?></span><p><?=sk1380_h($e['note'])?></p></div><?php endforeach;?></div><?php if($isProvider&&$order['status']!=='completed'):?><form method="post" class="status-form"><input type="hidden" name="_csrf" value="<?=sk1380_h(sk1380_csrf())?>"><input type="hidden" name="action" value="status"><select name="status"><option value="accepted">Accept booking</option><option value="on_the_way">On the way</option><option value="started">Work started</option><option value="completed">Work completed</option></select><input name="note" placeholder="Optional status note"><button>Update Status</button></form><?php endif;?><?php if($isCustomer&&$order['status']==='completed'):$rq=sk1380_db()->prepare('SELECT * FROM service_reviews_v1380 WHERE tenant_id=? AND order_id=?');$rq->execute([sk1380_tid(),$order['id']]);$rv=$rq->fetch(PDO::FETCH_ASSOC)?:[];?><h2>Review completed service</h2><form method="post" class="review-form"><input type="hidden" name="_csrf" value="<?=sk1380_h(sk1380_csrf())?>"><input type="hidden" name="action" value="review"><label>Rating<select name="rating"><?php for($i=5;$i>=1;$i--):?><option value="<?=$i?>" <?=($rv['rating']??5)==$i?'selected':''?>><?=$i?> stars</option><?php endfor;?></select></label><textarea name="review_text" placeholder="Share your experience"><?=sk1380_h($rv['review_text']??'')?></textarea><button>Save Review</button></form><?php endif;?></section><aside><h2>Booking chat</h2><div class="chat"><?php foreach($messages as $m):?><div class="<?=((int)$m['sender_user_id']===sk1380_uid())?'mine':''?>"><b><?=sk1380_h(sk1380_user_label((int)$m['sender_user_id']))?></b><p><?=sk1380_h($m['message'])?></p><small><?=sk1380_h(date('d M, h:i A',strtotime($m['created_at'])))?></small></div><?php endforeach;?></div><form method="post" class="chat-send"><input type="hidden" name="_csrf" value="<?=sk1380_h(sk1380_csrf())?>"><input type="hidden" name="action" value="message"><textarea name="message" placeholder="Write a booking message"></textarea><button>Send</button></form></aside></div><?php sk1380_end();